export function parseEuros(text) {
  const m = /^(\d{1,3}(?:,\d{3})*|\d+)(?:\.(\d{1,2}))?$/.exec(String(text).trim());
  if (!m) return fail('AMOUNT_INVALID');
  const euros = Number(m[1].replace(/,/g, ''));
  const cents = Number((m[2] ?? '').padEnd(2, '0'));
  return ok(euros * 100 + cents);
}

/**
 * Convert EUR cents to another currency.
 * @param {number} eurcents Amount in EUR cents
 * @param {string} currency Currency code (EUR, USD, GBP)
 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
 */
export function convert(eurcents, currency) {
  if (!(currency in RATES)) {
    return fail('UNKNOWN_CURRENCY');
  }

  const rate = RATES[currency];
  const converted = eurcents * rate / 100;
  const cents = roundCents(converted);
  return ok(cents);
}

/**
 * Format cents in a given currency for people: 123456 EUR -> "€1,234.56", 123456 USD -> "$1,234.56".
 * @param {number} cents Amount in that currency's cents
 * @param {string} currency Currency code (EUR, USD, GBP)
 * @returns {string}
 */
export function formatMoney(cents, currency) {
  const sign = cents < 0 ? '-' : '';
  const abs = Math.abs(cents);
  const units = Math.floor(abs / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  const centsStr = String(abs % 100).padStart(2, '0');

  let symbol = '€';
  if (currency === 'USD') symbol = '$';
  else if (currency === 'GBP') symbol = '£';

  return `${sign}${symbol}${units}.${centsStr}`;
}

