import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('roundCents with 124.5 rounds to even (124)', () => {
  assert.equal(roundCents(124.5), 124);
});

test('roundCents with 125.5 rounds to even (126)', () => {
  assert.equal(roundCents(125.5), 126);
});

test('roundCents with 2.4 rounds down (2)', () => {
  assert.equal(roundCents(2.4), 2);
});

test('roundCents with -0.5 rounds to 0', () => {
  assert.equal(roundCents(-0.5), 0);
});

test('RATES has EUR, USD, GBP', () => {
  assert.ok('EUR' in RATES);
  assert.ok('USD' in RATES);
  assert.ok('GBP' in RATES);
});

test('RATES EUR is 1', () => {
  assert.equal(RATES.EUR, 1);
});

test('RATES USD is 1.085', () => {
  assert.equal(RATES.USD, 1.085);
});

test('RATES GBP is 0.8425', () => {
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR to EUR returns same amount', () => {
  const result = convert(10000, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 10000);
});

test('convert EUR to USD with positive amount', () => {
  // 100.00 EUR = 10000 cents
  // 10000 * 1.085 / 100 = 1085 cents USD
  const result = convert(10000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1085);
});

test('convert EUR to GBP with positive amount', () => {
  // 100.00 EUR = 10000 cents
  // 10000 * 0.8425 / 100 = 842.5 cents -> 842 or 843 (banker's rounding)
  const result = convert(10000, 'GBP');
  assert.equal(result.ok, true);
  assert.equal(result.value, 843); // 842.5 rounds to even (843)
});

test('convert EUR to unknown currency returns error', () => {
  const result = convert(10000, 'JPY');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert with negative amount', () => {
  const result = convert(-10000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, -1085);
});

test('convert with zero amount', () => {
  const result = convert(0, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('convert with fractional result rounds correctly', () => {
  // Testing that roundCents is used for fractional results
  // 1 EUR cent = 1.085 USD cents, which is fractional
  const result = convert(1, 'USD');
  assert.equal(result.ok, true);
  // 1 * 1.085 / 100 = 0.01085 cents -> rounds to 0
  assert.equal(result.value, 0);
});

test('convert with amount that produces .5 fractional', () => {
  // Find an amount that produces exactly .5 after conversion
  // For GBP: need (amount * 0.8425 / 100) to end in .5
  // 10000 * 0.8425 / 100 = 842.5 -> rounds to 843 (banker's rounding)
  const result = convert(10000, 'GBP');
  assert.equal(result.value, 843);
});

test('formatEuros with basic amount', () => {
  assert.equal(formatEuros(123456), '€1,234.56');
});

test('formatEuros with negative amount', () => {
  assert.equal(formatEuros(-5), '-€0.05');
});

test('formatMoney EUR formats as euros', () => {
  assert.equal(formatMoney(123456, 'EUR'), '€1,234.56');
});

test('formatMoney USD formats with dollar sign', () => {
  assert.equal(formatMoney(123456, 'USD'), '$1,234.56');
});

test('formatMoney GBP formats with pound sign', () => {
  assert.equal(formatMoney(123456, 'GBP'), '£1,234.56');
});

test('formatMoney with negative USD amount', () => {
  assert.equal(formatMoney(-123456, 'USD'), '-$1,234.56');
});

test('formatMoney with negative GBP amount', () => {
  assert.equal(formatMoney(-123456, 'GBP'), '-£1,234.56');
});

test('formatMoney with zero amount', () => {
  assert.equal(formatMoney(0, 'USD'), '$0.00');
  assert.equal(formatMoney(0, 'GBP'), '£0.00');
  assert.equal(formatMoney(0, 'EUR'), '€0.00');
});

test('formatMoney with small amounts', () => {
  assert.equal(formatMoney(5, 'USD'), '$0.05');
  assert.equal(formatMoney(50, 'GBP'), '£0.50');
});

test('formatMoney with large amounts', () => {
  assert.equal(formatMoney(12345678, 'USD'), '$123,456.78');
  assert.equal(formatMoney(12345678, 'GBP'), '£123,456.78');
});

test('formatMoney with thousands separator', () => {
  assert.equal(formatMoney(1000000, 'USD'), '$10,000.00');
  assert.equal(formatMoney(1000000, 'GBP'), '£10,000.00');
});

test('convert and formatMoney together for invoice', () => {
  // EUR invoice for 1000.00 EUR
  const eurCents = 100000;
  const usdResult = convert(eurCents, 'USD');
  assert.equal(usdResult.ok, true);
  const formatted = formatMoney(usdResult.value, 'USD');
  // 100000 * 1.085 / 100 = 1085000 cents = $10,850.00
  assert.equal(formatted, '$10,850.00');
});

test('convert EUR to GBP and back (not exact due to rounding)', () => {
  const original = 100000; // 1000 EUR
  const gbpResult = convert(original, 'GBP');
  assert.equal(gbpResult.ok, true);
  // Going back: gbp * (1 / 0.8425) = gbp * 1.1869...
  // But we don't have a reverse convert, just testing that convert works both ways
  // 100000 EUR -> GBP
  // 100000 * 0.8425 / 100 = 84250 cents = £842.50
  assert.equal(gbpResult.value, 84250);
});

test('formatMoney preserves exact conversion', () => {
  const eurCents = 10000; // 100 EUR
  const gbpResult = convert(eurCents, 'GBP');
  const formatted = formatMoney(gbpResult.value, 'GBP');
  // 10000 * 0.8425 / 100 = 842.5 -> 843 cents = £8.43
  assert.equal(formatted, '£8.43');
});

test('convert multiple times maintains precision', () => {
  // Convert EUR to USD, format, convert to GBP, format
  const eurCents = 50000; // 500 EUR
  const usdResult = convert(eurCents, 'USD');
  assert.equal(usdResult.ok, true);
  // 50000 * 1.085 / 100 = 5425 cents USD
  assert.equal(usdResult.value, 5425);
  const usdFormatted = formatMoney(usdResult.value, 'USD');
  assert.equal(usdFormatted, '$54.25');
});

test('parseEuros and formatMoney round-trip', () => {
  // "1,234.56" -> 123456 cents -> format -> "€1,234.56"
  const parsed = parseEuros('1,234.56');
  assert.equal(parsed.ok, true);
  const formatted = formatMoney(parsed.value, 'EUR');
  assert.equal(formatted, '€1,234.56');
});

test('convert with fractional intermediate that rounds to different values', () => {
  // Test various amounts to ensure banker's rounding is used
  const test1 = convert(1162, 'GBP'); // 1162 * 0.8425 / 100 = 9.79675 cents
  assert.equal(test1.ok, true);
  // Should be rounded by roundCents

  const test2 = convert(100, 'USD'); // 100 * 1.085 / 100 = 1.085 cents
  assert.equal(test2.ok, true);
  // Should be rounded to 1 cent
  assert.equal(test2.value, 1);
});

